import { createHash } from 'node:crypto'
import { writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

/* Writes packages/core/src/datastar-bundle.ts: the Datastar browser bundle
   that hyper-effect serves from the app's own origin. Datastar 1.x is not on
   npm (the npm package stops at 1.0.0-beta.11), so the bundle comes from the
   release tag and must match the Subresource Integrity hash Datastar
   publishes for it. To upgrade: change VERSION and INTEGRITY, run this, run
   the tests. Usage: node tools/datastar/vendor.mjs */

const VERSION = '1.0.4'
const INTEGRITY = 'sha384-twbOvafhSBQ0rJDNPzJdUw6DRvthVgAVfSIG1BQVmCiNO7Qh2zeVn7T5qstgjJ9q'
const URL = `https://cdn.jsdelivr.net/gh/starfederation/datastar@${VERSION}/bundles/datastar.js`

const sha384 = text => `sha384-${createHash('sha384').update(text).digest('base64')}`

const response = await fetch(URL)
if (!response.ok) throw new Error(`${URL}: ${response.status}`)
const bundle = await response.text()
if (sha384(bundle) !== INTEGRITY) throw new Error(`${URL} does not match ${INTEGRITY}`)

// The source map is not served.
const served = bundle.replace(/\n\/\/# sourceMappingURL=\S+\s*$/, '\n')
const target = join(dirname(fileURLToPath(import.meta.url)), '..', '..', 'packages', 'core', 'src', 'datastar-bundle.ts')
writeFileSync(
  target,
  [
    `// Generated by tools/datastar/vendor.mjs from ${URL}`,
    `// (${INTEGRITY}). Do not edit.`,
    '//',
    '// Datastar, Copyright © Star Federation, MIT License: https://github.com/starfederation/datastar/blob/main/LICENSE.md',
    '',
    `export const DATASTAR_VERSION = '${VERSION}'`,
    '',
    '/** Subresource Integrity hash of `DATASTAR_SOURCE`. */',
    `export const DATASTAR_INTEGRITY = '${sha384(served)}'`,
    '',
    `export const DATASTAR_SOURCE = ${JSON.stringify(served)}`,
    '',
  ].join('\n'),
)
console.log(`datastar ${VERSION}: ${served.length} bytes -> ${target}`)
